const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im9vaWhueXFzc3F1YmdzaHZha3lnIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzA5MDIwNTIsImV4cCI6MjA4NjQ3ODA1Mn0.yZ0istNTaIm[...]';
const supabase = window.supabase.createClient(supabaseUrl, supabaseKey);

// লগইন চেক + UI আপডেট
let currentUser = null;

async function checkAuth() {
  const { data: { session } } = await supabase.auth.getSession();
  currentUser = session?.user || null;

  const userInfo = document.getElementById('user-info');
  const logoutBtn = document.getElementById('logout-btn');
  const authSection = document.getElementById('auth-section');

  if (currentUser) {
    userInfo.innerText = `Welcome, ${currentUser.email}`;
    logoutBtn.style.display = 'inline-block';
    if (authSection) authSection.style.display = 'none';
    loadHistory();
  } else {
    userInfo.innerText = '';
    logoutBtn.style.display = 'none';
    if (authSection) authSection.style.display = 'block';
  }
}

// হ্যামবার্গার মেনু টগল
function toggleMenu() {
  const menu = document.getElementById('menu');
  if (menu) {
    menu.classList.toggle('active');
  }
}

// Sign Up
async function signUp() {
  const email = document.getElementById('email').value.trim();
  const password = document.getElementById('password').value.trim();
  const msg = document.getElementById('auth-message');

  if (!email || !password) {
    if (msg) msg.innerText = 'Please enter email and password';
    return;
  }

  const { error } = await supabase.auth.signUp({ email, password });
  if (msg) {
    msg.innerText = error ? 'Error: ' + error.message : 'Account created! Check email to confirm.';
  }
}

// Login
async function login() {
  const email = document.getElementById('email').value.trim();
  const password = document.getElementById('password').value.trim();
  const msg = document.getElementById('auth-message');

  if (!email || !password) {
    if (msg) msg.innerText = 'Please enter email and password';
    return;
  }

  const { data, error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) {
    if (msg) msg.innerText = 'Login failed: ' + error.message;
  } else {
    if (msg) msg.innerText = 'Welcome, ' + data.user.email;
    checkAuth();
  }
}

// Log Out
async function logout() {
  await supabase.auth.signOut();
  checkAuth();
}

// QR সেভ করার ফাংশন (Supabase-এ)
async function saveQRToDatabase(qrContent, qrType = 'text') {
  if (!currentUser) {
    alert('Please log in to save your QR history.');
    return;
  }

  const { error } = await supabase
    .from('user_qr_history')
    .insert({
      user_id: currentUser.id,
      qr_content: qrContent,
      qr_type: qrType
    });

  if (error) {
    console.error('Save error:', error.message);
    alert('Failed to save: ' + error.message);
  } else {
    console.log('QR saved to Supabase');
  }
}

// হিস্ট্রি লোড করা (Supabase থেকে)
async function loadHistory() {
  if (!currentUser) {
    let qrHistory = JSON.parse(localStorage.getItem('qrHistory')) || [];
    renderHistory(qrHistory);
    return;
  }

  const { data, error } = await supabase
    .from('user_qr_history')
    .select('qr_content, created_at')
    .eq('user_id', currentUser.id)
    .order('created_at', { ascending: false });

  if (error) {
    console.error('Load error:', error.message);
    return;
  }

  renderHistory(data.map(item => ({
    text: item.qr_content,
    dataURL: '',
    created_at: item.created_at
  })));
}

// হিস্ট্রি দেখানো (render function)
function renderHistory(history) {
  const historyList = document.getElementById('history-list');
  if (!historyList) return;
  
  historyList.innerHTML = '';
  history.forEach((item, index) => {
    const div = document.createElement('div');
    div.className = 'history-item';
    div.innerHTML = `
      <span>${item.text}</span>
      ${item.dataURL ? `<img src="${item.dataURL}" alt="QR">` : ''}
      <button onclick="downloadHistory(${index}, '${item.text}')">ডাউনলোড</button>
    `;
    historyList.appendChild(div);
  });
}

// QR জেনারেট করা
function generateQR() {
  const textInput = document.getElementById('text-input');
  const text = textInput ? textInput.value.trim() : '';
  
  if (!text) return alert('টেক্সট লিখো!');

  const qrPreview = document.getElementById('qr-preview');
  if (!qrPreview) return;
  
  qrPreview.innerHTML = '';
  const qrcode = new QRCode(qrPreview, {
    text: text,
    width: 256,
    height: 256,
    colorDark: "#000000",
    colorLight: "#ffffff",
    correctLevel: QRCode.CorrectLevel.H
  });

  setTimeout(() => {
    const canvas = qrPreview.querySelector('canvas');
    if (canvas) {
      const dataURL = canvas.toDataURL('image/png');
      saveQRToDatabase(text);

      const downloadBtn = document.getElementById('download-btn');
      if (downloadBtn) {
        downloadBtn.style.display = 'block';
        downloadBtn.setAttribute('data-url', dataURL);
      }

      loadHistory();
    }
  }, 100);
}

// QR ডাউনলোড করা
function downloadQR() {
  const downloadBtn = document.getElementById('download-btn');
  if (!downloadBtn) return;
  
  const dataURL = downloadBtn.getAttribute('data-url');
  if (!dataURL) return alert('QR তৈরি করো আগে!');

  const link = document.createElement('a');
  link.href = dataURL;
  link.download = 'qrcode.png';
  link.click();
}

// হিস্ট্রি আইটেম ডাউনলোড করা
function downloadHistory(index, text) {
  const qrPreview = document.createElement('div');
  const qrcode = new QRCode(qrPreview, {
    text: text,
    width: 256,
    height: 256,
    colorDark: "#000000",
    colorLight: "#ffffff",
    correctLevel: QRCode.CorrectLevel.H
  });

  setTimeout(() => {
    const canvas = qrPreview.querySelector('canvas');
    if (canvas) {
      const link = document.createElement('a');
      link.href = canvas.toDataURL('image/png');
      link.download = `qrcode_${index}.png`;
      link.click();
    }
  }, 100);
}

// হিস্ট্রি ক্লিয়ার করা
function clearHistory() {
  if (confirm('নিশ্চিত?')) {
    if (currentUser) {
      supabase.from('user_qr_history').delete().eq('user_id', currentUser.id);
    }
    localStorage.removeItem('qrHistory');
    loadHistory();
  }
}

// প্রোফাইল সেভ এবং ডিসপ্লে করা
function saveAndDisplayProfile(name) {
  const profile = {
    name: name || 'Md Riyad',
    pic: ''
  };
  localStorage.setItem('profile', JSON.stringify(profile));
  
  const profileName = document.getElementById('profile-name');
  if (profileName) {
    profileName.innerText = profile.name;
  }
}

// প্রোফাইল আপডেট করা
function updateProfile() {
  const nameInput = document.getElementById('name-input');
  const name = nameInput ? nameInput.value.trim() : 'User';
  saveAndDisplayProfile(name);
  alert('প্রোফাইল আপডেট হয়েছে!');
}

// ইনিশিয়াল লোড
window.addEventListener('load', function() {
  checkAuth();
  let profile = JSON.parse(localStorage.getItem('profile')) || { name: 'Md Riyad', pic: '' };
  saveAndDisplayProfile(profile.name);
});
